import json,pathlib,sqlite3
root=pathlib.Path('materials'); questions=[]
def add(id,topic,title,prompt,hint,answer,checks,source,files,sql=None):
 q=dict(id=id,topic=topic,title=title,prompt=prompt,hint=hint,answer=answer,checks=checks,source=source,files=[str(p).replace('\\','/') for p in files]);
 if sql:
  db=next(root.rglob('Chinook_Sqlite.sqlite'));c=sqlite3.connect(db);q['expected']=c.execute(sql).fetchall();c.close();q['sql']=sql
 questions.append(q)
chin=next(root.rglob('Chinook_Sqlite.sqlite'));pwc=next(root.rglob('PWC SQL.docx'))
for id,title,prompt,sql,hint in [
 ('sql-1','Start with the population','How many rows are in the Invoice table? Write a SQL query and report the count.','SELECT COUNT(*) AS invoices FROM Invoice','COUNT(*) counts rows, including rows containing NULL values.'),
 ('sql-2','Find high-value invoices','How many invoices have totals strictly greater than $20?','SELECT COUNT(*) FROM Invoice WHERE Total > 20','Use WHERE before aggregation. An invoice equal to $20 does not qualify.'),
 ('sql-3','Define the interval','How many invoices have totals greater than $10 and less than $20?','SELECT COUNT(*) FROM Invoice WHERE Total > 10 AND Total < 20','BETWEEN includes its endpoints; the question asks for strict inequalities.'),
 ('sql-4','Filter three markets','How many invoices have a billing country of Brazil, Argentina, or Chile?','SELECT COUNT(*) FROM Invoice WHERE BillingCountry IN (\'Brazil\',\'Argentina\',\'Chile\')','IN is useful for membership in a list.'),
 ('sql-5','Recognise missing information','How many customers list their company?','SELECT COUNT(*) FROM Customer WHERE Company IS NOT NULL AND TRIM(Company) <> \'\'','A missing company is not the same as a company name. Check NULL and empty text.'),
 ('sql-6','Communicate the country totals','Return each billing country and total invoice value, highest total first.','SELECT BillingCountry, SUM(Total) AS revenue FROM Invoice GROUP BY BillingCountry ORDER BY revenue DESC, BillingCountry','Group by BillingCountry. Sum invoice totals directly so invoice-line joins do not duplicate revenue.'),
 ('sql-7','Join without losing meaning','Return the five tracks with the most units sold, showing track name and units. Break ties by TrackId ascending.','SELECT t.Name, SUM(il.Quantity) AS units FROM InvoiceLine il JOIN Track t ON t.TrackId=il.TrackId GROUP BY t.TrackId, t.Name ORDER BY units DESC, t.TrackId ASC LIMIT 5','Join InvoiceLine to Track on TrackId. Sum Quantity; use a deterministic tie break.')]:
 add(id,'SQL',title,prompt,hint,'Reference SQLite query:\n'+sql,['I used the requested population and filters.','I checked the unit of analysis and missing values.','I can explain the result and any ties.'],'PWC SQL.docx · Chinook assignment',[chin,pwc],sql)
etl=next(root.rglob('Analytics_mindset_case_studies_ETL.docx'));ec=list(root.rglob('Analytics_mindset_case_studies_ETL_Case*'))
add('etl-1','Excel & ETL','Import with intention','Inspect ETL Case 1. Import it into Excel, preserving the original data. Document the delimiter, column types, row count and missing values. Explain how you verified the import.','Open the source as text first. Compare imported row and column counts to the source.','Use comma-separated import for this file; explicitly inspect types, year, tickers and numeric fields. Keep raw data unchanged, record row counts, inspect blanks and validate totals before and after transformation.',['I documented delimiter and data types.','I retained the original data and row counts.','I reconciled totals and logged issues.'],'ETL case · extraction and messy data',[etl,ec[0]])
add('etl-2','Excel & ETL','Prevent a duplicated total','Using the ETL case discussion of joins and aggregation, explain why joining invoice totals to invoice-line records and summing those totals can overstate sales. Describe a repeatable fix.','What happens to a single invoice total when an invoice has three lines?','A header total repeats for every matching line. Aggregate lines to invoice level before joining, or sum the header table separately. Reconcile row counts, distinct invoice identifiers and control totals. Do not use SUM(DISTINCT total): different invoices can share the same value.',['I identified the grain of each table.','I explained the duplication mechanism.','I described a reconciliation and a repeatable fix.'],'ETL case · joining and aggregation',[etl])
inte=next(root.rglob('Analytics_mindset_case_studies_IntegrateCo_Excel.docx'));ifs=list(root.rglob('Analytics_mindset_case_studies_IntegrateCo_*.csv'))
add('pay-1','Payroll','Make two systems comparable','Prepare the 2015 and 2016 IntegrateCo files for a first-six-month comparison. Identify the stable employee key, common hours and wages definitions, and how you will extract job codes.','Employee_ID in the new system is not the same identifier as Employee_Number. Keep job codes as three-character text.','Match Emp_No (2015) to Employee_Number (2016). Gross wages in 2015 = Reg_Pay + OT_Pay; compare with Gross_Wages. Total hours = regular + overtime in each year. Extract the three-digit job code after the year and optional department letter; validate against 001–012. Aggregate both years to the same employee/job grain; 2016 has no pay dates.',['I matched the stable employee number.','I aligned wage and hour definitions.','I validated job codes and aggregation level.'],'IntegrateCo · Parts 1–2',[inte,*ifs])
add('pay-2','Payroll','Explain the payroll change','Build the IntegrateCo Part 3 job-code comparison: total hours, gross wages and gross wages per hour for each year. Include every valid job code and identify the three largest increases among codes present in both years.','Divide total wages by total hours; do not average individual hourly rates.','Use the job-code lookup as the complete list and join yearly aggregates onto it. Calculate weighted gross pay per hour as SUM(wages)/SUM(hours), guarding against zero denominators. For this practice task define change explicitly as 2016 minus 2015 (positive = increase). The source contains conflicting wording on subtraction; label your convention. Investigate employees behind the three largest eligible changes before recommending action.',['I included all valid job codes.','I used a weighted hourly cost and handled zero hours.','I labelled the change direction and traced drivers.'],'IntegrateCo · Part 3',[inte,*ifs])
rest=next(root.rglob('Instructions.docx'));data=next(root.rglob('data.xlsm'))
add('reg-1','Regression','Forecast for Bob','Merge the three restaurant sheets and build a regression to predict aggregated sales seven days after the last observed day. Explain the prediction, inputs and uncertainty to Bob.','First establish a common date grain. Check that joins do not multiply daily sales.','Aggregate product sales to a daily total, inspect the other sheets and join on validated dates. Specify a regression with predictors available for the forecast date. Calculate the date as maximum observed date plus seven days. Report the forecast and its uncertainty, assumptions and operational implication for ingredients and staffing. Do not promise an exact outcome.',['I verified date matching and daily totals.','I used predictors available at forecast time.','I explained uncertainty and a business decision.'],'Restaurant · forecast task',[rest,data])
add('reg-2','Regression','Interpret an effect','Using the restaurant case, investigate whether temperature and game days are associated with sales. Explain how the interaction of prior-year sales and a game day changes the interpretation.','An interaction changes the slope associated with another predictor.','Fit and document the relevant models. For an interaction model, Sales = b0 + b1×PriorYearSales + b2×GameDay + b3×PriorYearSales×GameDay. The prior-year slope is b1 on non-game days and b1+b3 on game days; game-day difference is b2+b3×PriorYearSales. Interpret estimates and uncertainty from your fitted output. An association alone does not establish causation.',['I specified the predictors and interaction.','I interpreted coefficients conditionally.','I discussed statistical uncertainty and causality.'],'Restaurant · temperature, game day and interaction tasks',[rest,data])
pc=next(root.rglob('Analytics_mindset_case_studies_PCard.docx'));db=next(root.rglob('pcards.db'))
add('audit-1','Audit','Turn a policy into a test','Using the P-card case, design a test for purchases above the $5,000 single-transaction ceiling. Explain the population, threshold, SQL logic and evidence needed before concluding a violation.','The file contains multiple agencies. Identify OSU and inspect transaction dates before filtering the 2014 calendar year.','Inspect distinct agency names/numbers, identify OSU and parse the actual TransactionDate format. Filter OSU transactions in calendar 2014 and Amount > 5000. The Year field may reflect a fiscal period, so verify its meaning. Review exceptions, approvals, receipts and the individual cardholder limit. A flagged row requires investigation; it is not proof of fraud.',['I scoped OSU and the correct dates.','I used a strict amount threshold.','I distinguished an exception from proven misconduct.'],'P-card · background, spending controls and Task 5',[pc,db])
add('audit-2','Audit','Investigate split purchases','Design a test for possible split purchases around the $5,000 limit. Explain your grouping choices, possible false positives and next audit steps.','Related transactions may use different cardholders, vendors or dates. A single grouping cannot catch every case.','Start with same-cardholder, same-vendor, same-day purchases below or equal to $5,000 whose combined amount exceeds $5,000. Restrict the agency and period, separate refunds and inspect dates. Review invoices and purchase purpose to establish whether a known purchase was split to evade a limit. Discuss missed splits across days, vendors or cardholders and unrelated legitimate purchases flagged by the rule.',['I specified the grouping and thresholds.','I considered refunds and alternative splitting patterns.','I requested corroborating evidence.'],'P-card · prohibited split purchases',[pc,db])
pathlib.Path('site/questions.json').write_text(json.dumps(questions,indent=2),encoding='utf-8')
print('Created',len(questions),'source-grounded questions with verified SQL results')
